  `customer_id` int DEFAULT NULL COMMENT '关联客户ID（关联 bas_customer.customer_id，定制料品归属客户）',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用：true=启用（可用于新建工单）, false=停用（历史数据保留）',
  `effective_date` datetime NOT NULL COMMENT '生效日期（料品档案的生效起始日，用于版本追溯）',
  `expiry_date` datetime NOT NULL COMMENT '失效日期（料品档案的有效期截止日）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`material_id`),
  UNIQUE KEY `material_code` (`material_code`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `bas_material_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `bas_customer` (`customer_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='料品档案表：存储生产用物料/半成品基础信息（尺寸、重量、客户等）';
