--
-- Table structure for table `bas_supplier`
--

DROP TABLE IF EXISTS `bas_supplier`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bas_supplier` (
  `supplier_id` int NOT NULL AUTO_INCREMENT COMMENT '供应商ID（主键）',
  `supplier_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '供应商编号（如 SUP-001 / SUP-ALUMINUM-002）',
  `supplier_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '供应商全称（营业执照上的公司全称）',
  `short_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商简称（前端下拉常用简称）',
  `supplier_category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商分类（如 铝材供应商 / 涂料供应商 / 设备厂商 / 检测机构）',
  `contact_person` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主要联系人姓名（采购对接人）',
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话（手机/座机均可）',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电子邮箱',
  `address` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系地址（详细地址，含省市区）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '启用状态：1=启用（可用于新建采购单）, 0=停用',
  `credit_level` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '信用等级（如 A / B / C，用于付款条件设定）',
  `tax_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纳税人识别号/统一社会信用代码',
  `bank_account` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '对公银行账号（用于付款）',
  `bank_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开户银行全称',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注说明（如合作年限、付款条件、特殊条款）',
  `sort_order` int DEFAULT '0' COMMENT '排序序号（供应商列表默认排序，数值小排前）',
  `created_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人（操作人 username）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`supplier_id`),
  UNIQUE KEY `supplier_code` (`supplier_code`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='供应商档案表：存储原材料/设备供应商基础信息、联系方式、信用等级';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `bas_supplier`
--

