--
-- Table structure for table `device_calibration_plan`
--

DROP TABLE IF EXISTS `device_calibration_plan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `device_calibration_plan` (
  `plan_id` int NOT NULL AUTO_INCREMENT COMMENT '校准计划ID（主键）',
  `asset_id` int NOT NULL COMMENT '资产ID（关联 master_device.device_id，设备/仪器统一）',
  `asset_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资产编号（冗余，来自 master_device.device_code）',
  `asset_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资产名称（冗余，来自 master_device.device_name）',
  `calibration_cycle` int NOT NULL COMMENT '校准周期（月，如 12=每年校准一次）',
  `last_calibration_date` date DEFAULT NULL COMMENT '上次校准完成日期（从最新一条 CalibrationRecord 回填）',
  `next_calibration_date` date DEFAULT NULL COMMENT '下次应校准日期（到期前系统提醒）',
  `calibration_org` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '建议/默认校准机构（如 国家计量院 / 内部计量室）',
  `calibration_items` json DEFAULT NULL COMMENT '校准项目明细（JSON 数组，每项含 {name, requirement, method}）',
  `status` tinyint DEFAULT '0' COMMENT '计划状态：0=待校准, 1=已校准, 2=已超期, 3=已锁定（停用）',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注说明（特殊校准要求等）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`plan_id`),
  KEY `device_calibration_plan_asset_id` (`asset_id`),
  KEY `device_calibration_plan_next_calibration_date` (`next_calibration_date`),
  KEY `device_calibration_plan_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='设备/仪器校准计划表：管理每台资产的校准周期和计划状态';
/*!40101 SET character_set_client = @saved_cs_client */;

