--
-- Table structure for table `device_calibration_record`
--

DROP TABLE IF EXISTS `device_calibration_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `device_calibration_record` (
  `record_id` int NOT NULL AUTO_INCREMENT COMMENT '校准记录ID（主键）',
  `plan_id` int NOT NULL COMMENT '校准计划ID（关联 device_calibration_plan.plan_id）',
  `asset_id` int DEFAULT NULL COMMENT '资产ID（冗余，关联 master_device.device_id）',
  `asset_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资产编号（冗余，来自 master_device.device_code）',
  `asset_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资产名称（冗余，来自 master_device.device_name）',
  `calibration_date` date NOT NULL COMMENT '校准完成日期（YYYY-MM-DD）',
  `calibration_org` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际校准机构名称（如 国家计量院 XX 分所）',
  `calibration_result` tinyint NOT NULL COMMENT '校准结果：1=合格（出校准证书）, 2=不合格（需整改或报废）',
  `certificate_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '校准证书编号（合格时由机构颁发的唯一编号）',
  `certificate_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '校准证书文件存储路径（PDF 上传后归档位置）',
  `valid_until` date DEFAULT NULL COMMENT '校准证书有效期（到期后需重新校准）',
  `cost` decimal(12,2) DEFAULT NULL COMMENT '校准费用（元，用于成本核算）',
  `calibration_items` json DEFAULT NULL COMMENT '实际校准项目结果（JSON 数组，每项含 {item_name, result, requirement}）',
  `operator_id` int DEFAULT NULL COMMENT '系统录入人ID（操作人，关联 sys_user.user_id）',
  `operator_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '系统录入人姓名（冗余，方便查询）',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注说明（不合格时的整改情况等）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`record_id`),
  KEY `device_calibration_record_plan_id` (`plan_id`),
  KEY `device_calibration_record_asset_id` (`asset_id`),
  KEY `device_calibration_record_calibration_date` (`calibration_date`),
  CONSTRAINT `device_calibration_record_ibfk_1` FOREIGN KEY (`plan_id`) REFERENCES `device_calibration_plan` (`plan_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='设备/仪器校准执行记录表：记录每次校准结果、证书、费用等';
/*!40101 SET character_set_client = @saved_cs_client */;

