--
-- Table structure for table `master_device`
--

DROP TABLE IF EXISTS `master_device`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `master_device` (
  `device_id` int NOT NULL AUTO_INCREMENT COMMENT '设备ID（主键，与 Instrument / 其他资产表共用）',
  `entity_type` enum('设备','仪器') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '设备' COMMENT '资产类型：设备=生产设备, 仪器=检测仪器',
  `device_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资产编号（系统内唯一，如 EQ-PRESS-001 / INS-CALI-015）',
  `device_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资产名称（中文显示名，如 1# 冲压机 / 数显卡尺-015）',
  `device_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资产类型/大类（如 冲压机 / 印刷机 / 灌装机 / 计量仪器）',
  `device_model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '型号规格（设备/仪器出厂型号，如 AIDA-2000）',
  `serial_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '出厂序列号（厂家生产 SN，用于溯源）',
  `location` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '放置位置（车间/工位，如 冲压车间 1#工位）',
  `line_id` int DEFAULT NULL COMMENT '所属产线ID（关联 master_production_line.line_id）',
  `responsible_person` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '责任人/保管人（员工姓名）',
  `is_special` tinyint(1) DEFAULT '0' COMMENT '是否特殊/关键设备：true=是（需重点维护和校准）, false=否',
  `status` tinyint DEFAULT '1' COMMENT '资产状态：1=正常（在用）, 0=停用, 2=维修中',
  `last_inspection_date` date DEFAULT NULL COMMENT '上次点检/保养日期（DATEONLY 格式 YYYY-MM-DD）',
  `inspection_cycle` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '点检/保养周期（如 每日 / 每周 / 每月 / 每季度 / 每半年）',
  `next_inspection_date` date DEFAULT NULL COMMENT '下次应点检/保养日期（系统自动计算，也可手动调整）',
  `manufacturer` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生产厂家（设备/仪器制造商）',
  `purchase_date` date DEFAULT NULL COMMENT '购置/入库日期',
  `warranty_end` date DEFAULT NULL COMMENT '质保到期日（超期后维修费自理）',
  `precision` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '精度要求（仅仪器有值，如 ±0.01mm / ±1%FS）',
  `department` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属部门（如 冲压车间 / 质量部 / 研发中心）',
  `calibration_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '校准类型：外校=第三方机构 / 内校=内部校准 / 不需要校准',
  `calibration_cycle` int DEFAULT NULL COMMENT '校准周期（天，如 365=每年校准一次）',
  `last_calibration_date` date DEFAULT NULL COMMENT '上次校准完成日期',
  `next_calibration_date` date DEFAULT NULL COMMENT '下次应校准日期（到期前系统提醒）',
  `supplier` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商名称（购置渠道）',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注说明（其他需要记录的信息）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`device_id`),
  UNIQUE KEY `device_code` (`device_code`),
  KEY `idx_entity_type` (`entity_type`),
  KEY `master_device_entity_type` (`entity_type`),
  KEY `master_device_status` (`status`),
  KEY `fk_device_line` (`line_id`),
  CONSTRAINT `fk_device_line` FOREIGN KEY (`line_id`) REFERENCES `master_production_line` (`line_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=93 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='设备/仪器主数据表：统一管理生产设备和检测仪器基础信息';
/*!40101 SET character_set_client = @saved_cs_client */;

