-- Table structure for table `production_manpower_record`
--

DROP TABLE IF EXISTS `production_manpower_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_manpower_record` (
  `record_id` int NOT NULL AUTO_INCREMENT COMMENT '记录ID（主键，报工人员工时记录）',
  `report_order_id` int DEFAULT NULL COMMENT '生产报工单ID',
  `record_date` date DEFAULT NULL COMMENT '记录日期',
  `shift` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '班次',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `skilled_count` int DEFAULT '0' COMMENT '熟手人数',
  `general_count` int DEFAULT '0' COMMENT '普工人数',
  `labor_count` int DEFAULT '0' COMMENT '劳务人数',
  `other_count` int DEFAULT '0' COMMENT '其他人数',
  `total_people` int DEFAULT '0' COMMENT '总人数',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `record_user` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '记录人',
  `record_user_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '记录人姓名',
  `created_at` datetime NOT NULL,
  `hours` decimal(10,2) GENERATED ALWAYS AS ((case when ((`end_time` is not null) and (`start_time` is not null)) then round((timestampdiff(MINUTE,`start_time`,`end_time`) / 60),2) else 0.00 end)) STORED,
  `man_hours` decimal(10,2) GENERATED ALWAYS AS ((case when ((`end_time` is not null) and (`start_time` is not null)) then round(((timestampdiff(MINUTE,`start_time`,`end_time`) / 60) * coalesce(nullif(`total_people`,0),(((`skilled_count` + `general_count`) + `labor_count`) + `other_count`))),2) else 0.00 end)) STORED,
  `net_hours` decimal(10,2) DEFAULT '0.00' COMMENT '净工时（小时，扣除休息时间）',
  PRIMARY KEY (`record_id`),
  KEY `report_order_id` (`report_order_id`),
  CONSTRAINT `production_manpower_record_ibfk_1` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='生产报工人员工时记录表：记录每个报工单的出勤人员、班次、工时等';
/*!40101 SET character_set_client = @saved_cs_client */;

