--
-- Table structure for table `production_order`
--

DROP TABLE IF EXISTS `production_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_order` (
  `order_id` int NOT NULL AUTO_INCREMENT COMMENT '订单ID（主键）',
  `order_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生产订单号（来自 U9 或本地生成，如 MO20261031001）',
  `material_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品ID（关联 bas_material.material_id，UUID 类型主键）',
  `material_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品编码（冗余，来自 bas_material.material_code）',
  `material_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品名称（冗余，来自 bas_material.material_name）',
  `specification` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格型号（冗余，来自 bas_material.specification）',
  `film_version` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菲林编号/版本（来自料品档案 film_no）',
  `version_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版本号（料品设计版本，如 V1 / V2.1）',
  `planned_qty` decimal(12,2) DEFAULT '0.00' COMMENT '计划生产数量（订单要求数量）',
  `finished_qty` decimal(12,2) DEFAULT '0.00' COMMENT '累计完工数量（从 MES 报工单汇总回填）',
  `u9_qualified` decimal(12,2) DEFAULT '0.00' COMMENT 'U9 同步的累计合格数量（U9 端返回）',
  `plan_start_time` datetime DEFAULT NULL COMMENT '计划开工时间（排产时设定）',
  `plan_end_time` datetime DEFAULT NULL COMMENT '计划完工时间（排产时设定）',
  `u9_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'U9 原始状态字符串（如 开立 / 开工 / 完工 / 关闭，保留 U9 原始值）',
  `status` tinyint DEFAULT '0' COMMENT 'MES 本地状态：0=开立, 1=下发, 2=开工, 3=完工, 4=关闭',
  `release_time` datetime DEFAULT NULL COMMENT '下发/开工时间（订单状态转为开工时记录）',
  `close_time` datetime DEFAULT NULL COMMENT '完工关闭时间（订单状态转为关闭时记录）',
  `created_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人（操作人 username，自动或手动创建时记录）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `barcode` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品条形码（生产追溯扫码用）',
  PRIMARY KEY (`order_id`),
  UNIQUE KEY `order_no` (`order_no`),
  KEY `idx_order_dates` (`plan_start_time`,`plan_end_time`),
  KEY `idx_order_material` (`material_id`)
) ENGINE=InnoDB AUTO_INCREMENT=291 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='生产订单主表：从 U9 同步或本地创建，驱动整条生产链路';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `production_order`
--

LOCK TABLES `production_order` WRITE;
/*!40000 ALTER TABLE `production_order` DISABLE KEYS */;
