--
-- Table structure for table `production_process_defect`
--

DROP TABLE IF EXISTS `production_process_defect`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_process_defect` (
  `defect_id` int NOT NULL AUTO_INCREMENT COMMENT '不良记录ID（主键）',
  `report_order_id` int DEFAULT NULL COMMENT '生产报工单ID',
  `process_id` int DEFAULT NULL COMMENT '工序ID',
  `defect_type_id` int DEFAULT NULL COMMENT '不良分类ID',
  `quantity` decimal(12,2) DEFAULT '0.00' COMMENT '数量',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `defect_images` text COLLATE utf8mb4_unicode_ci COMMENT '不良图片(JSON数组)',
  `record_time` datetime NOT NULL,
  PRIMARY KEY (`defect_id`),
  KEY `report_order_id` (`report_order_id`),
  KEY `defect_type_id` (`defect_type_id`),
  KEY `idx_pd_report` (`report_order_id`),
  KEY `idx_pd_type` (`defect_type_id`,`record_time`),
  KEY `fk_ppd_process` (`process_id`),
  CONSTRAINT `fk_ppd_process` FOREIGN KEY (`process_id`) REFERENCES `master_process` (`process_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `production_process_defect_ibfk_1` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `production_process_defect_ibfk_2` FOREIGN KEY (`defect_type_id`) REFERENCES `master_defect_type` (`defect_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=506 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='报工不良记录表：记录每次报工的不良品数量、分类、图片等';
/*!40101 SET character_set_client = @saved_cs_client */;

