--
-- Table structure for table `production_process_exception`
--

DROP TABLE IF EXISTS `production_process_exception`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_process_exception` (
  `exception_id` int NOT NULL AUTO_INCREMENT COMMENT '异常记录ID（主键）',
  `report_order_id` int DEFAULT NULL COMMENT '生产报工单ID',
  `exception_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常类型',
  `device_id` int DEFAULT NULL COMMENT '设备ID',
  `device_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备编码',
  `device_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备名称',
  `stop_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '停机类型',
  `confirm_user` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '确认人',
  `confirm_user_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '确认人姓名',
  `start_time` datetime DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '恢复时间',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常描述',
  `exception_images` text COLLATE utf8mb4_unicode_ci COMMENT '异常图片，JSON数组存储',
  `record_user` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '记录人',
  `record_user_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '记录人姓名',
  `created_at` datetime NOT NULL,
  `duration` decimal(10,2) GENERATED ALWAYS AS ((case when ((`end_time` is not null) and (`start_time` is not null)) then round((timestampdiff(MINUTE,`start_time`,`end_time`) / 60),2) else 0.00 end)) STORED,
  `net_duration` decimal(10,2) DEFAULT '0.00' COMMENT '净停机时长（小时，扣除休息时间）',
  PRIMARY KEY (`exception_id`),
  KEY `report_order_id` (`report_order_id`),
  KEY `idx_pe_report` (`report_order_id`),
  KEY `idx_pe_time` (`start_time`,`end_time`),
  CONSTRAINT `fk_ppe_report` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `production_process_exception_ibfk_1` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=144 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='报工异常停机记录表：记录生产过程中的设备异常、停机时间等';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `production_process_exception`
