--
-- Table structure for table `production_process_material`
--

DROP TABLE IF EXISTS `production_process_material`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_process_material` (
  `material_id` int NOT NULL AUTO_INCREMENT COMMENT '物料记录ID（主键）',
  `report_order_id` int DEFAULT NULL COMMENT '生产报工单ID',
  `process_id` int DEFAULT NULL COMMENT '工序ID',
  `material_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料类型',
  `bas_material_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联基础料品表ID',
  `material_batch` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '物料批次',
  `package_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '包号',
  `quantity` decimal(12,2) DEFAULT '0.00' COMMENT '数量',
  `label_images` text COLLATE utf8mb4_unicode_ci COMMENT '标签图片(JSON)',
  `record_time` datetime NOT NULL,
  PRIMARY KEY (`material_id`),
  KEY `report_order_id` (`report_order_id`),
  KEY `idx_pm_report` (`report_order_id`),
  KEY `idx_pm_process` (`report_order_id`,`process_id`),
  KEY `idx_ppm_bas_material` (`bas_material_id`),
  KEY `fk_ppm_process` (`process_id`),
  CONSTRAINT `fk_ppm_bas_material` FOREIGN KEY (`bas_material_id`) REFERENCES `bas_material` (`material_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_ppm_process` FOREIGN KEY (`process_id`) REFERENCES `master_process` (`process_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `production_process_material_ibfk_1` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=207 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='报工物料记录表：记录每次报工的投料物料、批次、包号等';
/*!40101 SET character_set_client = @saved_cs_client */;

