DROP TABLE IF EXISTS `production_report_image`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_report_image` (
  `image_id` int NOT NULL AUTO_INCREMENT COMMENT '图片ID（主键）',
  `report_order_id` int NOT NULL COMMENT '关联生产报工单ID',
  `category` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '图片分类：defect=不良, label=标签, exception=异常',
  `image_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '图片URL',
  `file_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件哈希（MD5/SHA-256，用于去重）',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`image_id`),
  KEY `report_order_id` (`report_order_id`),
  CONSTRAINT `production_report_image_ibfk_1` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='报工单图片子表：统一存储报工单的不良/标签/异常图片';
/*!40101 SET character_set_client = @saved_cs_client */;

