--
-- Table structure for table `production_report_order`
--

DROP TABLE IF EXISTS `production_report_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_report_order` (
  `report_order_id` int NOT NULL AUTO_INCREMENT COMMENT '生产报工单ID',
  `order_id` int NOT NULL COMMENT '关联生产订单ID',
  `order_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单号（冗余）',
  `report_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '报工单号（WO-16+YYMMDD+3位序号）',
  `line_id` int DEFAULT NULL COMMENT '生产产线ID',
  `line_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产线名称（冗余）',
  `material_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品ID（从订单带出）',
  `material_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料号（冗余）',
  `material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品名称（冗余）',
  `specification` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格（冗余）',
  `report_qty` decimal(12,2) DEFAULT '0.00' COMMENT '报工数量',
  `report_time` datetime DEFAULT NULL COMMENT '报工时间（创建时间）',
  `finish_time` datetime DEFAULT NULL COMMENT '完工时间',
  `status` tinyint DEFAULT '0' COMMENT '工单状态：0=开工, 1=完工',
  `report_user_id` int DEFAULT NULL COMMENT '报工人员ID',
  `report_user_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报工人员姓名（冗余）',
  `finish_user_id` int DEFAULT NULL COMMENT '完工人员ID',
  `finish_user_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '完工人员姓名（冗余）',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `production_batch` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生产批号（完工必填）',
  `image_first` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首张合格证 URL（同步 production_report_image）',
  `image_last` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '末张合格证 URL（同步 production_report_image）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `close_time` datetime DEFAULT NULL COMMENT '关闭时间',
  `close_user_id` int DEFAULT NULL COMMENT '关闭人员ID',
  `close_user_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关闭人员姓名（冗余）',
  `break_minutes` int DEFAULT '0' COMMENT '休息总分钟数（后端汇总写入）',
  PRIMARY KEY (`report_order_id`),
  UNIQUE KEY `report_no` (`report_no`),
  KEY `order_id` (`order_id`),
  KEY `material_id` (`material_id`),
  KEY `idx_report_order` (`order_id`),
  KEY `idx_report_line_status` (`report_time`,`line_id`,`status`),
  KEY `fk_pro_line` (`line_id`),
  CONSTRAINT `fk_pro_line` FOREIGN KEY (`line_id`) REFERENCES `master_production_line` (`line_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `production_report_order_ibfk_1` FOREIGN KEY (`order_id`) REFERENCES `production_order` (`order_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `production_report_order_ibfk_2` FOREIGN KEY (`material_id`) REFERENCES `bas_material` (`material_id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='生产报工单主表：记录每笔生产报工的产出数量、报工人员、工序完成情况';
/*!40101 SET character_set_client = @saved_cs_client */;

