  PRIMARY KEY (`id`),
  UNIQUE KEY `production_report_process_report_order_id_process_id` (`report_order_id`,`process_id`),
  KEY `production_report_process_report_order_id` (`report_order_id`),
  KEY `idx_rp_report` (`report_order_id`),
  KEY `idx_rp_order_process` (`report_order_id`,`process_id`),
  KEY `fk_rpp_process` (`process_id`),
  CONSTRAINT `fk_rpp_process` FOREIGN KEY (`process_id`) REFERENCES `master_process` (`process_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `production_report_process_ibfk_1` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=496 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='报工工序列表：创建报工单时从产线工序表继承的工序列表（快照）';
