--
-- Table structure for table `qc_inspection_item`
--

DROP TABLE IF EXISTS `qc_inspection_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `qc_inspection_item` (
  `item_id` int NOT NULL AUTO_INCREMENT COMMENT '统一检验项ID',
  `source_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源类型：来料/产品/微生物（多态外键类型标识）',
  `inspection_id` int NOT NULL COMMENT '多态外键，关联三主表inspection_id（无物理FK约束，应用层保证）',
  `item_cfg_id` int DEFAULT NULL COMMENT '关联quality_inspection_standard_item.item_id（可空，旧数据无）',
  `item_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验项目名称',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目大类',
  `standard_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标准值（定性描述保留）',
  `actual_value_text` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '兼容旧数据/单值场景/定性值汇总',
  `sample_count` int DEFAULT NULL COMMENT '实际抽样数',
  `summary` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '汇总如8件全合格',
  `result` tinyint DEFAULT NULL COMMENT '0不合格/1合格（综合判定）',
  `inspector_id` int DEFAULT NULL COMMENT '项目检验人ID',
  `inspector_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '冗余',
  `inspection_time` datetime DEFAULT NULL COMMENT '项目检验时间',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `item_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目类型：qualitative定性(仅判定OK/NG) / quantitative定量(记录测量数值)',
  `need_sample_count` int DEFAULT '0' COMMENT '默认抽样数（来自检验标准），0=不限制由实际抽样决定',
  `upper_limit` decimal(15,4) DEFAULT NULL COMMENT '上限（定量用，来自检验标准）',
  `lower_limit` decimal(15,4) DEFAULT NULL COMMENT '下限（定量用，来自检验标准）',
  `sampling_plan` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '抽样方案：AQL抽样/按数量抽样/固定数量抽样/全检',
  `sampling_detail` text COLLATE utf8mb4_unicode_ci COMMENT '抽样方案详情JSON（Ac/Re等）',
  `accept_number` int DEFAULT NULL COMMENT '允收值 Ac',
  `reject_number` int DEFAULT NULL COMMENT '拒收值 Re',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL,
