--
-- Table structure for table `quality_incoming_inspection_item`
--

DROP TABLE IF EXISTS `quality_incoming_inspection_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_incoming_inspection_item` (
  `item_id` int NOT NULL AUTO_INCREMENT COMMENT '检验项目ID',
  `inspection_id` int NOT NULL COMMENT '关联来料检验主表ID',
  `item_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验项目名称',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目分类(大类)',
  `standard_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目标准值',
  `actual_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目检测值',
  `result` tinyint DEFAULT NULL COMMENT '项目判定结果：0=不合格, 1=合格',
  `inspector_id` int DEFAULT NULL COMMENT '项目检验人ID',
  `inspector_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目检验人姓名（冗余）',
  `inspection_time` datetime DEFAULT NULL COMMENT '项目检验时间',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`item_id`),
  KEY `quality_incoming_inspection_item_inspection_id` (`inspection_id`),
  KEY `quality_incoming_inspection_item_result` (`result`),
  CONSTRAINT `quality_incoming_inspection_item_ibfk_1` FOREIGN KEY (`inspection_id`) REFERENCES `quality_incoming_inspection` (`inspection_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

