--
-- Table structure for table `quality_inspection_standard`
--

DROP TABLE IF EXISTS `quality_inspection_standard`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_inspection_standard` (
  `standard_id` int NOT NULL AUTO_INCREMENT COMMENT '检验标准ID',
  `standard_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准编号',
  `standard_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准名称',
  `inspection_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '检验类型：首件/制程/成品/其它（已废弃，移至子表 inspection_types）',
  `standard_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准类型：材料检验/产品检验/环境检验/微生物检验标准/其它检验',
  `customer_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户编码',
  `material_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参照料品ID',
  `material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品名称（冗余）',
  `version_no` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'V1' COMMENT '版本号',
  `effective_date` datetime DEFAULT NULL COMMENT '生效日期',
  `expiry_date` datetime DEFAULT NULL COMMENT '失效日期',
