) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='检验方案主表：定义某类检验的总体要求（关联 StandardItem 明细）';
