--
-- Table structure for table `quality_inspection_standard_item`
--

DROP TABLE IF EXISTS `quality_inspection_standard_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_inspection_standard_item` (
  `item_id` int NOT NULL AUTO_INCREMENT COMMENT '检验标准项目ID',
  `standard_id` int NOT NULL COMMENT '关联检验标准ID',
  `item_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目大类：外观/尺寸/性能/理化/微生物/环境',
  `method` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验方法',
  `standard_value` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准值',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `defect_level` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '缺陷等级：A类致命缺陷、B类严重缺陷、C类次要缺陷',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `inspection_types` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验类型（多选，逗号分隔：首件,制程,成品,来料,其它）',
  `item_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目类型：qualitative定性(仅判定OK/NG) / quantitative定量(记录测量数值)',
  `need_sample_count` int NOT NULL DEFAULT '0' COMMENT '默认抽样数，0=不限制由实际抽样决定',
  `upper_limit` decimal(15,4) DEFAULT NULL COMMENT '上限（定量用，可空）',
  `lower_limit` decimal(15,4) DEFAULT NULL COMMENT '下限（定量用，可空）',
  `accept_number` int DEFAULT NULL COMMENT '允收值Ac',
  `reject_number` int DEFAULT NULL COMMENT '拒收值Re',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `sampling_plan` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '抽样方案：AQL抽样/按数量抽样/固定数量抽样/全检',
  `sampling_detail` text COLLATE utf8mb4_unicode_ci COMMENT '抽样方案详情JSON：AQL值/分段数量/固定数量/Ac/Re',
  PRIMARY KEY (`item_id`),
  KEY `quality_inspection_standard_item_standard_id` (`standard_id`),
  CONSTRAINT `quality_inspection_standard_item_ibfk_1` FOREIGN KEY (`standard_id`) REFERENCES `quality_inspection_standard` (`standard_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=490 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='检验方案明细表：定义每个检验项目的标准值、公差、检测方法';
/*!40101 SET character_set_client = @saved_cs_client */;

