INSERT INTO `quality_inspection_standard_item` VALUES (216,1,'外观检查-印刷图案','感官要求','目视检查','图案清晰、完整、位置正确，无明显色差','处','C类次要缺陷',1,'首件,制程,成品','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:47','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(217,1,'外观检查-表面划痕','感官要求','目视检查','无明显划痕、凹坑、变形','处','C类次要缺陷',2,'首件,制程,成品','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:47','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(218,1,'外观检查-焊缝质量','感官要求','目视检查','焊缝均匀光滑，无虚焊、漏焊、气孔','处','C类次要缺陷',3,'首件,制程,成品','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:47','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(219,1,'尺寸-罐体直径','尺寸要求','游标卡尺测量','φ126.5±0.2','mm','B类严重缺陷',4,'首件,制程,成品','quantitative',5,126.7000,126.3000,NULL,NULL,'2026-08-15 19:03:47','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(220,1,'尺寸-罐体高度','尺寸要求','高度尺测量','H(罐高)±0.3','mm','B类严重缺陷',5,'首件,制程,成品','qualitative',5,NULL,NULL,NULL,NULL,'2026-08-15 19:03:47','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(221,1,'尺寸-卷边宽度','尺寸要求','游标卡尺测量','2.8±0.2','mm','B类严重缺陷',6,'首件,制程,成品','quantitative',5,3.0000,2.6000,NULL,NULL,'2026-08-15 19:03:47','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(222,1,'性能-密封性试验','理化性能要求','真空检漏仪','无泄漏，压力衰减≤0.05MPa/30s','MPa','A类致命缺陷',7,'首件,制程,成品','quantitative',3,0.0500,NULL,NULL,NULL,'2026-08-15 19:03:47','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(223,1,'理化-涂层附着力','理化性能要求','百格测试','涂层无脱落，等级≥4B','B','B类严重缺陷',8,'首件','quantitative',3,NULL,4.0000,NULL,NULL,'2026-08-15 19:03:47','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(224,4,'线径尺寸','理化性能要求','游标卡尺','Φ1.38 + 0.00 /‑0.04mm','mm','B类严重缺陷',0,'来料','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:52','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(225,4,'抗拉强度','理化性能要求','核对COA','225‑285','N/mm²','B类严重缺陷',0,'来料','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:52','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(226,4,'伸长率','理化性能要求','核对COA','≥20','%','B类严重缺陷',0,'来料','quantitative',0,NULL,20.0000,NULL,NULL,'2026-08-15 19:03:52','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(227,4,'表面质量','感官要求','目视检查','无裂纹、起皮、毛刺、粗拉道、折叠、夹杂；局部轻微缺陷不超公差、不影响焊接允许；轻微氧化、水迹油迹不影响焊接不报废','处','C类次要缺陷',0,'来料','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:52','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(228,6,'彩印面外观','感官要求','目视（光源CY/T 3-1999，距离750~800mm，眼距350~400mm）；25倍放大镜检查网点','无油污、虫害、锈蚀、异物、漏印、墨染、留空带料、折痕；主要部位无划伤，次要部位轻微划伤≤3处；图案清晰，无倒置、混版；网点清晰无重影','-','A类致命缺陷',1,'','quantitative',0,3.0000,NULL,NULL,NULL,'2026-08-15 19:03:57','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(229,6,'色差','感官要求','目视比对','颜色、光泽与客户样板相符，同批无明显偏差','-','B类严重缺陷',2,'','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:57','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(230,6,'套印误差','感官要求','25倍刻度放大镜，测3点取平均值','≤0.2 mm（特殊要求除外）','mm','B类严重缺陷',3,'','quantitative',0,0.2000,NULL,NULL,NULL,'2026-08-15 19:03:57','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(231,6,'条形码','感官要求','条码检测仪','符合GB/T 18348-2022','-','A类致命缺陷',4,'','quantitative',0,20370.0000,16326.0000,NULL,NULL,'2026-08-15 19:03:57','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(232,6,'素铁面外观','感官要求','目视','无油污、虫害、锈蚀、异物、手指印；无露铁支架伤、带料、划伤、折痕、内印色','-','A类致命缺陷',5,'','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:57','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(233,6,'附着力','理化性能要求','划痕仪+3M胶带撕拉，评级表','≥Ⅱ级（划圈法）','-','B类严重缺陷',6,'','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:57','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(234,6,'抗冲击性（彩印面）','理化性能要求','QCJ冲击器+4倍放大镜','冲锤1kg，500mm下落，漆膜无裂纹、不脱落，无密集腐蚀点','-','B类严重缺陷',7,'','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:57','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(235,6,'抗冲击性（涂膜面）','理化性能要求','落锤冲击仪+硫酸铜溶液','1kg，1m下落，硫酸铜浸泡30min，无腐蚀斑','-','B类严重缺陷',8,'','qualitative',0,NULL,NULL,NULL,NULL,'2026-08-15 19:03:57','2026-08-19 10:21:35','AQL抽样','{\"aql_value\":2.5}'),(236,6,'抗划伤','理化性能要求','划痕测试仪，砝码加载，3张各划2次','底盖外涂/罐身≥800g；白墨+光油≥1000g；白瓷+光油≥