--
-- Table structure for table `quality_instrument`
--

DROP TABLE IF EXISTS `quality_instrument`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_instrument` (
  `instrument_id` int NOT NULL AUTO_INCREMENT,
  `instrument_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仪器编号（用户手动输入，生成后不可修改）',
  `instrument_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仪器名称',
  `instrument_model` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '型号',
  `precision` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备精度',
  `department` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用部门',
  `location` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '存放地点',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '在用' COMMENT '状态：在用/停用',
  `calibration_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '校验类型：外校/内校/不需要校准',
  `calibration_cycle` int DEFAULT NULL COMMENT '校准周期（天）',
  `last_calibration_date` date DEFAULT NULL COMMENT '上次校准日期',
  `next_calibration_date` date DEFAULT NULL COMMENT '下次校准日期',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `supplier` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`instrument_id`),
  UNIQUE KEY `instrument_no` (`instrument_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='检测仪器台账';
/*!40101 SET character_set_client = @saved_cs_client */;

