--
-- Table structure for table `quality_microbe_inspection`
--

DROP TABLE IF EXISTS `quality_microbe_inspection`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_microbe_inspection` (
  `inspection_id` int NOT NULL AUTO_INCREMENT COMMENT '微生物检验ID',
  `inspection_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验编号（前缀MB+日期+序号）',
  `inspection_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '正常' COMMENT '检验类型：正常/加严/复检',
  `object_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验对象：成品检验/来料检验',
  `report_order_id` int DEFAULT NULL COMMENT '关联报工单ID（成品检验时）',
  `report_order_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报工单号（冗余）',
  `incoming_id` int DEFAULT NULL COMMENT '关联来料检验ID（来料检验时）',
  `incoming_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来料检验单号（冗余）',
  `order_id` int DEFAULT NULL COMMENT '关联生产订单ID',
  `order_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单编号（冗余）',
  `material_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品ID',
  `material_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料号（冗余）',
  `material_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料品名称（冗余）',
  `specification` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格（冗余）',
  `standard_id` int DEFAULT NULL COMMENT '关联检验标准ID',
  `standard_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验标准名称（冗余）',
  `result` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '总结果：合格/不合格',
  `handle_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理方式：入库/判退/报废/让步接收',
  `trigger_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '自动' COMMENT '触发方式：自动/手工',
  `status` tinyint DEFAULT '0' COMMENT '状态：0=待检, 1=检验中, 2=审核中, 3=已完成, 4=已关闭',
  `inspector_id` int DEFAULT NULL COMMENT '检验人ID',
  `inspector_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验人姓名（冗余）',
  `reviewer_id` int DEFAULT NULL COMMENT '审核人ID',
  `reviewer_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人姓名（冗余）',
  `inspection_time` datetime DEFAULT NULL COMMENT '检验时间',
  `review_time` datetime DEFAULT NULL COMMENT '审核时间',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`inspection_id`),
  UNIQUE KEY `inspection_no` (`inspection_no`),
  UNIQUE KEY `quality_microbe_inspection_inspection_no` (`inspection_no`),
  KEY `idx_object_type` (`object_type`),
  KEY `idx_report_order_id` (`report_order_id`),
  KEY `idx_incoming_id` (`incoming_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_status` (`status`),
  KEY `idx_created_at` (`created_at`),
  KEY `quality_microbe_inspection_object_type` (`object_type`),
  KEY `quality_microbe_inspection_report_order_id` (`report_order_id`),
  KEY `quality_microbe_inspection_incoming_id` (`incoming_id`),
  KEY `quality_microbe_inspection_order_id` (`order_id`),
  KEY `quality_microbe_inspection_status` (`status`),
  KEY `quality_microbe_inspection_created_at` (`created_at`),
  CONSTRAINT `fk_micro_order` FOREIGN KEY (`order_id`) REFERENCES `production_order` (`order_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_micro_report` FOREIGN KEY (`report_order_id`) REFERENCES `production_report_order` (`report_order_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='微生物检验单表：记录食品接触材料/产品的微生物检测结果';
/*!40101 SET character_set_client = @saved_cs_client */;

