-- Table structure for table `quality_process_inspection`
--

DROP TABLE IF EXISTS `quality_process_inspection`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quality_process_inspection` (
  `inspection_id` int NOT NULL AUTO_INCREMENT COMMENT '过程检验ID',
  `inspection_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检验编号（GC+YYMMDD+3位序号）',
  `report_order_id` int DEFAULT NULL COMMENT '关联生产报工单ID（在制品来源）',
  `work_order_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报工单号（冗余，便于移动端展示）',
  `process_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工序名称（冗余）',
  `product_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品名称（冗余）',
  `material_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '料号（冗余）',
  `quantity` decimal(12,2) DEFAULT NULL COMMENT '检验时数量',
  `temperature` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '温度（°C）',
  `humidity` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '湿度（%）',
  `ph` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'pH 值',
  `params_extra` text COLLATE utf8mb4_unicode_ci COMMENT '扩展参数 JSON（如压力、转速等附加项）',
  `result` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '总结果：合格/不合格',
  `handle_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理方式',
  `handle_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理原因',
  `status` tinyint DEFAULT '0' COMMENT '状态：0=待检, 1=检验中, 2=已完成, 3=已关闭',
  `inspector_id` int DEFAULT NULL COMMENT '检验人ID',
  `inspector_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检验人姓名（冗余）',
  `inspection_time` datetime DEFAULT NULL COMMENT '检验时间',
  `remarks` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`inspection_id`),
  UNIQUE KEY `inspection_no` (`inspection_no`),
  UNIQUE KEY `quality_process_inspection_inspection_no` (`inspection_no`),
  KEY `quality_process_inspection_report_order_id` (`report_order_id`),
  KEY `quality_process_inspection_status` (`status`),
  KEY `quality_process_inspection_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='过程检验单表：记录生产过程中的在制品抽检结果';
