INSERT INTO `sys_data_dictionary` VALUES (1,'sys_config','系统表','系统配置表，存储系统参数配置项',9,13,'[{\"name\":\"config_id\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":true,\"defaultValue\":null,\"comment\":\"配置ID（主键）\"},{\"name\":\"config_key\",\"type\":\"VARCHAR(100)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"配置键名（英文唯一标识，如 token_expire_seconds / upload_max_size）\"},{\"name\":\"config_value\",\"type\":\"TEXT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"配置值（以字符串存储，按 config_type 解析）\"},{\"name\":\"config_type\",\"type\":\"VARCHAR(20)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"string\",\"comment\":\"配置值类型（决定解析方式）：string / number / boolean / json\"},{\"name\":\"config_group\",\"type\":\"VARCHAR(50)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"system\",\"comment\":\"配置分组（用于前端菜单展示）：security / system / business / upload / ...\"},{\"name\":\"config_desc\",\"type\":\"VARCHAR(200)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"配置项说明（中文描述配置用途）\"},{\"name\":\"updated_by\",\"type\":\"VARCHAR(50)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"最后修改人（操作人 username）\"},{\"name\":\"created_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"创建时间\"},{\"name\":\"updated_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"更新时间\"}]','2026-11-04 14:24:44','2026-07-09 16:37:41','2026-11-04 14:24:44'),(2,'sys_dict_data','系统表','数据字典项表',12,27,'[{\"name\":\"dict_code\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":true,\"defaultValue\":null,\"comment\":\"字典数据ID（主键）\"},{\"name\":\"dict_sort\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"0\",\"comment\":\"字典项排序序号（同级按此排序显示）\"},{\"name\":\"dict_label\",\"type\":\"VARCHAR(100)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"字典项显示标签（如 一般 / 严重 / 紧急，前端下拉/单选显示）\"},{\"name\":\"dict_value\",\"type\":\"VARCHAR(100)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"字典项值（如 1 / 2 / 3，后端存储用的实际值）\"},{\"name\":\"dict_type\",\"type\":\"VARCHAR(100)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"所属字典类型编码（关联 sys_dict_type.dict_type）\"},{\"name\":\"css_class\",\"type\":\"VARCHAR(100)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"前端自定义 CSS 类名（用于特殊样式展示）\"},{\"name\":\"list_class\",\"type\":\"VARCHAR(100)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"前端列表样式类名（如 ant-tag-red 标签色）\"},{\"name\":\"is_default\",\"type\":\"TINYINT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"0\",\"comment\":\"是否该字典类型的默认选项：0=否, 1=是\"},{\"name\":\"status\",\"type\":\"TINYINT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"1\",\"comment\":\"字典项状态：1=启用, 0=禁用（禁用后前端不下发）\"},{\"name\":\"remark\",\"type\":\"VARCHAR(500)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"备注说明\"},{\"name\":\"created_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"创建时间\"},{\"name\":\"updated_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"更新时间\"}]','2026-11-04 14:24:44','2026-07-09 16:37:41','2026-11-04 14:24:44'),(3,'sys_dict_type','系统表','数据字典类型表',8,10,'[{\"name\":\"dict_id\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":true,\"defaultValue\":null,\"comment\":\"字典类型ID（主键）\"},{\"name\":\"dict_name\",\"type\":\"VARCHAR(100)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"字典类型中文名称（如 故障等级 / 工单状态）\"},{\"name\":\"dict_type\",\"type\":\"VARCHAR(100)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"字典类型编码（英文唯一标识，如 fault_level / order_status）\"},{\"name\":\"status\",\"type\":\"TINYINT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"1\",\"comment\":\"字典状态：1=启用, 0=禁用\"},{\"name\":\"remark\",\"type\":\"VARCHAR(500)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"备注说明（用途、与哪个业务模块关联等）\"},{\"name\":\"created_by\",\"type\":\"VARCHAR(50)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"创建人（操作人 username）\"},{\"name\":\"created_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"创建时间\"},{\"name\":\"updated_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"更新时间\"}]','2026-11-04 14:24:44','2026-07-09 16:37:41','2026-11-04 14:24:44'),(4,'sys_number_rule','系统表','编码规则表，用于系统自动编号的可视化配置管理',19,12,'[{\"name\":\"rule_id\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":true,\"defaultValue\":null,\"comment\":\"编号规则ID（主键）\"},{\"name\":\"rule_name\",\"type\":\"VARCHAR(100)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"规则名称（如 生产订单号 / 工单号 / 来料检验单号）\"},{\"name\":\"rule_code\",\"type\":\"VARCHAR(50)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"规则编码（英文唯一标识，同时也是 sys_sequence.seq_key，如 ORDER / WORK_ORDER）\"},{\"name\":\"prefix\",\"type\":\"VARCHAR(20)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"编号前缀（如 MO / WO / LL / F 等，生成编号时的首段）\"},{\"name\":\"date_format\",\"type\":\"VARCHAR(20)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"YYMMDD\",\"comment\":\"日期段格式：none=无日期, YYMMDD=261031, YYYYMMDD=20261031, YYYY=2026\"},{\"name\":\"separator\",\"type\":\"VARCHAR(5)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"\",\"comment\":\"各段之间的分隔符（如 - 或 / 或空字符串）\"},{\"name\":\"seq_width\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"3\",\"comment\":\"序号位数（左侧补零，如 3 位 → 001 / 002；常用 3-6 位）\"},{\"name\":\"reset_by\",\"type\":\"VARCHAR(20)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"daily\",\"comment\":\"序号重置周期：daily=每日重置, yearly=每年重置, never=永不重置\"},{\"name\":\"target_table\",\"type\":\"VARCHAR(100)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"关联业务表名（如 production_order / work_order，便于溯源）\"},{\"name\":\"target_field\",\"type\":\"VARCHAR(100)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"关联字段名（如 order_no / work_order_no，便于溯源）\"},{\"name\":\"target_label\",\"type\":\"VARCHAR(100)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"关联字段中文说明（如 订单编号，前端展示用）\"},{\"name\":\"current_no\",\"type\":\"VARCHAR(50)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"最新生成的完整编号（冗余，展示用；如 WO-261031-0123）\"},{\"name\":\"used_count\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"0\",\"comment\":\"已使用的编号总数（用于统计和追溯）\"},{\"name\":\"status\",\"type\":\"TINYINT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"1\",\"comment\":\"规则状态：1=启用（编号生成时使用）, 0=停用\"},{\"name\":\"is_locked\",\"type\":\"TINYINT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"0\",\"comment\":\"是否已审核锁定：0=未锁定（可修改核心配置）, 1=已锁定（核心配置不可改）\"},{\"name\":\"description\",\"type\":\"VARCHAR(500)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"规则说明（备注/用途说明）\"},{\"name\":\"created_by\",\"type\":\"VARCHAR(50)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"创建人（操作人 username）\"},{\"name\":\"created_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"创建时间\"},{\"name\":\"updated_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"更新时间\"}]','2026-11-04 14:24:44','2026-07-09 16:37:41','2026-11-04 14:24:44'),(5,'sys_operation_log','系统表','操作日志表，记录用户所有关键操作行为',13,2695,'[{\"name\":\"log_id\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":true,\"defaultValue\":null,\"comment\":\"日志ID（主键）\"},{\"name\":\"user_id\",\"type\":\"INT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"操作人用户ID（关联 sys_user.user_id，冗余）\"},{\"name\":\"username\",\"type\":\"VARCHAR(50)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"操作人登录账号（冗余，方便查询）\"},{\"name\":\"module\",\"type\":\"VARCHAR(50)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"操作模块（如 设备管理 / 工单管理 / 系统设置）\"},{\"name\":\"action\",\"type\":\"VARCHAR(50)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"操作类型（如 查询 / 新增 / 修改 / 删除 / 导出 / 登录）\"},{\"name\":\"operation\",\"type\":\"VARCHAR(100)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"操作描述（简短一句话，如 新增设备故障 F20261031001）\"},{\"name\":\"content\",\"type\":\"TEXT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"操作详情（较长的描述或数据快照，可选）\"},{\"name\":\"method\",\"type\":\"VARCHAR(10)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"HTTP 请求方法（GET / POST / PUT / DELETE）\"},{\"name\":\"params\",\"type\":\"TEXT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"请求参数（JSON 字符串，敏感字段已脱敏）\"},{\"name\":\"ip\",\"type\":\"VARCHAR(45)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"客户端 IP（兼容 IPv6）\"},{\"name\":\"ip_address\",\"type\":\"VARCHAR(45)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"同上（部分调用处用 ip 部分用 ip_address，同义冗余字段）\"},{\"name\":\"status\",\"type\":\"TINYINT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":\"1\",\"comment\":\"操作结果：1=成功, 0=失败\"},{\"name\":\"created_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"创建时间\"}]','2026-11-04 14:24:44','2026-07-09 16:37:41','2026-11-04 14:24:44'),(6,'sys_permission','系统表','系统权限表，存储菜单、页面、按钮、API权限定义',12,146,'[{\"name\":\"perm_id\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":true,\"defaultValue\":null,\"comment\":\"权限ID（主键）\"},{\"name\":\"parent_id\",\"type\":\"INT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":\"0\",\"comment\":\"父级权限ID（0=顶级节点，自关联形成树形结构）\"},{\"name\":\"perm_name\",\"type\":\"VARCHAR(50)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"权限名称（显示在菜单上的中文名称）\"},{\"name\":\"perm_code\",\"type\":\"VARCHAR(100)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"权限编码（英文唯一标识，如 device:fault:create）\"},{\"name\":\"type\",\"type\":\"VARCHAR(20)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"menu\",\"comment\":\"权限类型：menu=菜单, button=按钮, api=接口\"},{\"name\":\"icon\",\"type\":\"VARCHAR(100)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"菜单图标（Ant Design 图标名，仅 type=menu 有值）\"},{\"name\":\"path\",\"type\":\"VARCHAR(200)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"前端路由路径（如 /device/fault，仅 type=menu 有值）\"},{\"name\":\"component\",\"type\":\"VARCHAR(200)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"前端组件路径（如 pages/device/Fault，仅 type=menu 有值）\"},{\"name\":\"sort_order\",\"type\":\"INT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":\"0\",\"comment\":\"同级排序序号（数值小排前）\"},{\"name\":\"visible\",\"type\":\"TINYINT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"1\",\"comment\":\"是否在前端菜单显示：1=显示（可见可访问）, 0=隐藏（不可见但可访问）\"},{\"name\":\"status\",\"type\":\"TINYINT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":\"1\",\"comment\":\"权限状态：1=启用（角色可分配）, 0=禁用（角色不可分配，接口也被拦截）\"},{\"name\":\"created_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"创建时间\"}]','2026-11-04 14:24:44','2026-07-09 16:37:41','2026-11-04 14:24:44'),(7,'sys_role','系统表','系统角色表，定义角色名称、编码及排序',11,11,'[{\"name\":\"role_id\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":true,\"defaultValue\":null,\"comment\":\"角色ID（主键）\"},{\"name\":\"role_name\",\"type\":\"VARCHAR(50)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"角色名称（如 系统管理员 / 生产主管）\"},{\"name\":\"role_code\",\"type\":\"VARCHAR(50)\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"角色编码（英文唯一标识，如 admin / production_manager）\"},{\"name\":\"type\",\"type\":\"VARCHAR(20)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"角色类型（如 system=系统角色 / custom=自定义角色）\"},{\"name\":\"is_system_default\",\"type\":\"TINYINT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":\"0\",\"comment\":\"是否系统预置角色：0=否（可删除）, 1=是（不可删除）\"},{\"name\":\"description\",\"type\":\"VARCHAR(200)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"角色描述/说明\"},{\"name\":\"scope\",\"type\":\"VARCHAR(50)\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"数据权限范围（如 all=全部 / self=仅本人 / dept=本部门）\"},{\"name\":\"sort_order\",\"type\":\"INT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":\"0\",\"comment\":\"排序序号（数值小排前）\"},{\"name\":\"status\",\"type\":\"TINYINT\",\"nullable\":true,\"primaryKey\":false,\"defaultValue\":\"1\",\"comment\":\"角色状态：1=启用, 0=禁用\"},{\"name\":\"created_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"创建时间\"},{\"name\":\"updated_at\",\"type\":\"DATETIME\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"更新时间\"}]','2026-11-04 14:24:44','2026-07-09 16:37:41','2026-11-04 14:24:44'),(8,'sys_role_permission','系统表','角色权限关联表，建立角色与权限的多对多关系',3,358,'[{\"name\":\"id\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":true,\"defaultValue\":null,\"comment\":\"关联记录ID（主键）\"},{\"name\":\"role_id\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"角色ID（关联 sys_role.role_id）\"},{\"name\":\"perm_id\",\"type\":\"INT\",\"nullable\":false,\"primaryKey\":false,\"defaultValue\":null,\"comment\":\"权限ID（关联 sys_permission.perm_id）\"}]','2026-11-04 14:24:44','2026-07-09 16:37:4