DROP TABLE IF EXISTS `sys_number_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_number_rule` (
  `rule_id` int NOT NULL AUTO_INCREMENT COMMENT '编号规则ID（主键）',
  `rule_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则名称（如 生产订单号 / 工单号 / 来料检验单号）',
  `rule_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则编码（英文唯一标识，同时也是 sys_sequence.seq_key，如 ORDER / WORK_ORDER）',
  `prefix` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '编号前缀（如 MO / WO / LL / F 等，生成编号时的首段）',
  `date_format` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'YYMMDD' COMMENT '日期段格式：none=无日期, YYMMDD=261031, YYYYMMDD=20261031, YYYY=2026',
  `separator` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '各段之间的分隔符（如 - 或 / 或空字符串）',
  `seq_width` int NOT NULL DEFAULT '3' COMMENT '序号位数（左侧补零，如 3 位 → 001 / 002；常用 3-6 位）',
  `reset_by` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'daily' COMMENT '序号重置周期：daily=每日重置, yearly=每年重置, never=永不重置',
  `target_table` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联业务表名（如 production_order / work_order，便于溯源）',
  `target_field` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联字段名（如 order_no / work_order_no，便于溯源）',
  `target_label` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联字段中文说明（如 订单编号，前端展示用）',
  `current_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最新生成的完整编号（冗余，展示用；如 WO-261031-0123）',
  `used_count` int NOT NULL DEFAULT '0' COMMENT '已使用的编号总数（用于统计和追溯）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '规则状态：1=启用（编号生成时使用）, 0=停用',
  `is_locked` tinyint NOT NULL DEFAULT '0' COMMENT '是否已审核锁定：0=未锁定（可修改核心配置）, 1=已锁定（核心配置不可改）',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规则说明（备注/用途说明）',
  `created_by` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建人（操作人 username）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`rule_id`),
  UNIQUE KEY `rule_code` (`rule_code`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='编号规则配置表：前缀+日期+序号+分隔符的可视化编号模板';
/*!40101 SET character_set_client = @saved_cs_client */;

