--
-- Table structure for table `sys_operation_log`
--

DROP TABLE IF EXISTS `sys_operation_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_operation_log` (
  `log_id` int NOT NULL AUTO_INCREMENT COMMENT '日志ID（主键）',
  `user_id` int DEFAULT NULL COMMENT '操作人用户ID（关联 sys_user.user_id，冗余）',
  `username` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人登录账号（冗余，方便查询）',
  `module` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作模块（如 设备管理 / 工单管理 / 系统设置）',
  `action` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作类型（如 查询 / 新增 / 修改 / 删除 / 导出 / 登录）',
  `operation` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作描述（简短一句话，如 新增设备故障 F20261031001）',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '操作详情（较长的描述或数据快照，可选）',
  `method` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'HTTP 请求方法（GET / POST / PUT / DELETE）',
  `params` text COLLATE utf8mb4_unicode_ci COMMENT '请求参数（JSON 字符串，敏感字段已脱敏）',
  `ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户端 IP（兼容 IPv6）',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '同上（部分调用处用 ip 部分用 ip_address，同义冗余字段）',
  `status` tinyint DEFAULT '1' COMMENT '操作结果：1=成功, 0=失败',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`log_id`),
  KEY `idx_oplog_user_time` (`user_id`,`created_at`),
  KEY `idx_oplog_module_time` (`module`,`created_at`),
  CONSTRAINT `fk_oplog_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3723 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='操作日志表：记录用户登录/查询/增删改等操作，用于审计追溯';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_operation_log`
--

LOCK TABLES `sys_operation_log` WRITE;
/*!40000 ALTER TABLE `sys_operation_log` DISABLE KEYS */;
