--
-- Table structure for table `sys_permission`
--

DROP TABLE IF EXISTS `sys_permission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_permission` (
  `perm_id` int NOT NULL AUTO_INCREMENT COMMENT '权限ID（主键）',
  `parent_id` int DEFAULT '0' COMMENT '父级权限ID（0=顶级节点，自关联形成树形结构）',
  `perm_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权限名称（显示在菜单上的中文名称）',
  `perm_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权限编码（英文唯一标识，如 device:fault:create）',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'menu' COMMENT '权限类型：menu=菜单, button=按钮, api=接口',
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菜单图标（Ant Design 图标名，仅 type=menu 有值）',
  `path` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端路由路径（如 /device/fault，仅 type=menu 有值）',
  `component` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端组件路径（如 pages/device/Fault，仅 type=menu 有值）',
  `sort_order` int DEFAULT '0' COMMENT '同级排序序号（数值小排前）',
  `visible` tinyint NOT NULL DEFAULT '1' COMMENT '是否在前端菜单显示：1=显示（可见可访问）, 0=隐藏（不可见但可访问）',
  `status` tinyint DEFAULT '1' COMMENT '权限状态：1=启用（角色可分配）, 0=禁用（角色不可分配，接口也被拦截）',
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`perm_id`),
  UNIQUE KEY `perm_code` (`perm_code`)
) ENGINE=InnoDB AUTO_INCREMENT=758 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统权限/菜单表：树形结构，定义菜单、按钮、接口权限';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sys_permission`
--

LOCK TABLES `sys_permission` WRITE;
/*!40000 ALTER TABLE `sys_permission` DISABLE KEYS */;
