--
-- Table structure for table `sys_role`
--

DROP TABLE IF EXISTS `sys_role`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_role` (
  `role_id` int NOT NULL AUTO_INCREMENT COMMENT '角色ID（主键）',
  `role_name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色名称（如 系统管理员 / 生产主管）',
  `role_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色编码（英文唯一标识，如 admin / production_manager）',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色类型（如 system=系统角色 / custom=自定义角色）',
  `is_system_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否系统预置角色：0=否（可删除）, 1=是（不可删除）',
  `description` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色描述/说明',
  `scope` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '数据权限范围（如 all=全部 / self=仅本人 / dept=本部门）',
  `sort_order` int DEFAULT '0' COMMENT '排序序号（数值小排前）',
  `status` tinyint DEFAULT '1' COMMENT '角色状态：1=启用, 0=禁用',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`role_id`),
  UNIQUE KEY `role_code` (`role_code`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统角色表：定义角色、角色编码及状态';
/*!40101 SET character_set_client = @saved_cs_client */;

