  `seq_key` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '序列类型键（如 ORDER / WORK_ORDER / INCOMING，对应 NumberRule.rule_code）',
  `seq_date` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '序列日期（按日重置用 YYYYMMDD，按年重置用 YYYY，永不用空字符串）',
  `current_value` int NOT NULL DEFAULT '0' COMMENT '当前序号值（已成功分配的最新值，下次取号时 +1）',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`seq_id`),
  UNIQUE KEY `sys_sequence_seq_key_seq_date` (`seq_key`,`seq_date`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='业务编号序列表：原子化自增编号生成器（按日/年/永不重置）';
