DROP TABLE IF EXISTS `sys_system_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_system_log` (
  `log_id` int NOT NULL AUTO_INCREMENT COMMENT '日志ID（主键）',
  `level` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '日志级别（INFO / WARN / ERROR）',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '日志分类（如 request / auth / migration / sync — 从 pino 结构化 fields 提取）',
  `message` text COLLATE utf8mb4_unicode_ci COMMENT '日志消息（人类可读的简短摘要）',
  `details` text COLLATE utf8mb4_unicode_ci COMMENT '完整 JSON 载荷（pino 原始 log 对象 JSON 序列化，含 request/error/stack 等详情）',
  `duration_ms` int DEFAULT NULL COMMENT '请求耗时（毫秒，仅 request 类日志有值）',
  `path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求路径（仅 request 类日志有值）',
  `method` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'HTTP 方法（仅 request 类日志有值）',
  `status` int DEFAULT NULL COMMENT 'HTTP 状态码（仅 request 类日志有值）',
  `source` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '日志来源模块（如 logger.ts / middleware / service）',
  `created_at` datetime NOT NULL COMMENT '记录创建时间（服务器本地时区，Sequelize +08:00 自动转北京时间 DATETIME）',
  PRIMARY KEY (`log_id`),
  KEY `sys_system_log_level` (`level`),
  KEY `sys_system_log_created_at` (`created_at`),
  KEY `sys_system_log_path` (`path`)
) ENGINE=InnoDB AUTO_INCREMENT=11489 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统日志表：记录服务器运行时的结构化 pino 日志（info/warn/error），用于运维诊断';
/*!40101 SET character_set_client = @saved_cs_client */;

